   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

  /* Use the PolyBench symbolic loop bound. This may differ from n when
     the benchmark is run in "mini" or "large" modes. */
  const int N = _PB_N;

  /* Extra O(N) workspace: reciprocal of the diagonal entries of U.
     This replaces many expensive divisions with cheaper multiplications:

        - In the L update: A[i][j] /= A[j][j]  ->  A[i][j] *= diag_inv[j]
        - In back substitution: w /= A[i][i]  ->  w *= diag_inv[i]

     The cost is only N additional DATA_TYPE values, negligible compared to
     the N^2 matrix A. */
  DATA_TYPE diag_inv[_PB_N];

#pragma scop
  /* ------------------------------------------------------------------
   * 1. In-place LU factorization (Doolittle, no pivoting).
   *
   *    A is overwritten with L and U:
   *      - L in strict lower triangle (unit diagonal is implicit),
   *      - U in upper triangle including the diagonal.
   *
   *    Optimizations:
   *      - Reuse row pointer Ai to avoid repeated address arithmetic.
   *      - Replace divisions by A[j][j] with multiplications by
   *        precomputed diag_inv[j].
   *      - For the U-part, use a rank-1 update formulation:
   *
   *          for k = 0..i-1:
   *            A[i, i:N) -= L(i,k) * U(k, i:N)
   *
   *        which has contiguous access in j and is vectorization-friendly.
   * ------------------------------------------------------------------ */
  for (i = 0; i < N; i++) {
    DATA_TYPE *restrict Ai = A[i];

    /* ---- L-part: compute A[i][j] for j < i (strict lower triangle). ----
       L(i,j) = ( A_orig(i,j) - sum_{k<j} L(i,k) * U(k,j) ) / U(j,j)
       We compute the numerator as in the original code, but use
       diag_inv[j] = 1 / U(j,j) instead of a division by A[j][j]. */
    for (j = 0; j < i; j++) {
      w = Ai[j];
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A[k][j];
      }
      /* U(j,j) is already finalized when row j was processed, so
         diag_inv[j] has been computed. */
      Ai[j] = w * diag_inv[j];
    }

    /* ---- U-part: compute A[i][j] for j >= i (upper triangle). ----
       Original code:

         for (j = i; j < N; ++j) {
           w = A[i][j];
           for (k = 0; k < i; ++k)
             w -= A[i][k] * A[k][j];
           A[i][j] = w;
         }

       We reformulate this as a sequence of rank-1 updates:

         for (k = 0; k < i; ++k) {
           Lik = L(i,k);
           A[i, i:N) -= Lik * U(k, i:N);
         }

       For each fixed (i,j), the product A[i][k] * A[k][j] is subtracted
       in the same k-order (0..i-1), so the floating-point result for
       A[i][j] is identical to the original code, just applied in-place. */
    for (k = 0; k < i; k++) {
      const DATA_TYPE Lik = Ai[k];      /* L(i,k), already computed above */
      const DATA_TYPE *restrict Ak = A[k];

      /* j-loop over contiguous memory in the row-major layout.
         Marked with ivdep to help the compiler vectorize it. */
#pragma GCC ivdep
      for (j = i; j < N; j++) {
        Ai[j] -= Lik * Ak[j];
      }
    }

    /* Cache reciprocal of the diagonal entry U(i,i) for later use. */
    diag_inv[i] = (DATA_TYPE)1.0 / Ai[i];
  }

  /* ------------------------------------------------------------------
   * 2. Forward substitution: solve L * y = b.
   *    L has unit diagonal and is stored in the strict lower triangle.
   *
   *    y[i] = b[i] - sum_{j < i} L(i,j) * y[j]
   *
   *    The outer loop over i is inherently sequential, but the inner
   *    loop has no loop-carried dependencies and is light enough that
   *    the compiler will typically unroll/vectorize it at -O3. We reuse
   *    the row pointer Ai for better locality.
   * ------------------------------------------------------------------ */
  for (i = 0; i < N; i++) {
    DATA_TYPE *restrict Ai = A[i];
    w = b[i];
    for (j = 0; j < i; j++) {
      w -= Ai[j] * y[j];
    }
    y[i] = w;
  }

  /* ------------------------------------------------------------------
   * 3. Backward substitution: solve U * x = y.
   *    U is upper-triangular and stored in the upper triangle of A.
   *
   *    x[i] = ( y[i] - sum_{j > i} U(i,j) * x[j] ) / U(i,i)
   *
   *    We again replace the division by U(i,i) with multiplication by
   *    diag_inv[i] to avoid an expensive scalar division.
   * ------------------------------------------------------------------ */
  for (i = N - 1; i >= 0; i--) {
    const DATA_TYPE *restrict Ai = A[i];
    w = y[i];
#pragma GCC ivdep
    for (j = i + 1; j < N; j++) {
      w -= Ai[j] * x[j];
    }
    x[i] = w * diag_inv[i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
