  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

  /* Reciprocal of the diagonal of U: invD[i] = 1 / A[i][i]
     Used in L-factor updates and backward substitution. */
  DATA_TYPE invD[n];

#pragma scop
  /* In-place LU factorization (Doolittle, no pivoting). */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute L(i, 0..i-1): strict lower part of row i.
       L(i,j) = (A(i,j) - sum_{k<j} L(i,k) * U(k,j)) / U(j,j)
       We implement the division via multiplication by invD[j]. */
    for (j = 0; j < i; j++)
    {
      DATA_TYPE *restrict Aj = A_[j];

      w = Ai[j];
      for (k = 0; k < j; k++)
      {
        w -= Ai[k] * Aj[k];
      }

      /* For i > j, row j has already been fully factorized,
         so invD[j] = 1 / A[j][j] is available. */
      Ai[j] = w * invD[j];
    }

    /* Compute U(i, i..N-1): upper part of row i including the diagonal.
       Reformulated as a sequence of rank-1 updates:
         A[i, j] -= L(i, k) * U(k, j)  for k = 0..i-1, j = i..N-1.
       This preserves the per-(i,j) accumulation order over k and
       traverses contiguous elements in j. */
    for (k = 0; k < i; k++)
    {
      const DATA_TYPE Aik = Ai[k];
      const DATA_TYPE *restrict Ak = A_[k];

      /* j-loop has no loop-carried dependencies and is over
         contiguous memory; good target for SIMD. */
      for (j = i; j < _PB_N; j++)
      {
        Ai[j] -= Aik * Ak[j];
      }
    }

    /* U(i,i) is finalized; cache its reciprocal for future rows
       and for the backward substitution. */
    invD[i] = (DATA_TYPE)(1.0) / Ai[i];
  }

  /* Forward substitution: solve L * y = b.
     L has unit diagonal stored implicitly (A[i][i] is U's diagonal). */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];

    w = b_[i];
    for (j = 0; j < i; j++)
    {
      w -= Ai[j] * y_[j];
    }
    y_[i] = w;
  }

  /* Backward substitution: solve U * x = y.
     Use precomputed invD[i] instead of dividing by A[i][i]. */
  for (i = _PB_N - 1; i >= 0; i--)
  {
    DATA_TYPE *restrict Ai = A_[i];

    w = y_[i];
    for (j = i + 1; j < _PB_N; j++)
    {
      w -= Ai[j] * x_[j];
    }
    x_[i] = w * invD[i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

