      for (k = 0; k < k_end; k += 4) {
        const DATA_TYPE * restrict Ak0 = A[k];
        const DATA_TYPE * restrict Ak1 = A[k + 1];
        const DATA_TYPE * restrict Ak2 = A[k + 2];
        const DATA_TYPE * restrict Ak3 = A[k + 3];

        w -= Ai[k]     * Ak0[j];
        w -= Ai[k + 1] * Ak1[j];
        w -= Ai[k + 2] * Ak2[j];
        w -= Ai[k + 3] * Ak3[j];
      }
      for (; k < j; ++k) {
        w -= Ai[k] * A[k][j];
      }

