    /* We rewrite the original j–k nest:

           for (j = i; j < n; ++j) {
             w = A[i][j];
             for (k = 0; k < i; ++k)
               w -= A[i][k] * A[k][j];
             A[i][j] = w;
           }

       as a rank-1 update style:

           for (k = 0; k < i; ++k) {
             for (j = i; j < n; ++j)
               A[i][j] -= A[i][k] * A[k][j];
           }

       For each fixed (i,j), the sequence of subtractions over k is
       unchanged (k still increases from 0 to i-1), so the floating-point
       behavior for that element is preserved. The advantage is that j
       becomes the innermost loop over contiguous memory, which improves
       cache locality and enables efficient vectorization. */
    for (k = 0; k < i; ++k) {
      const DATA_TYPE aik = Ai[k];
      const DATA_TYPE * restrict Ak = A[k];

      /* Tile j to operate on chunks of the row that fit better in cache. */
      int jb;
      for (jb = i; jb < n_pb; jb += TILE_J) {
        const int j_max = (jb + TILE_J < n_pb) ? (jb + TILE_J) : n_pb;

        int jj;
        /* Unroll by 4 across j to increase ILP, still preserving the
           original j-ordering for each fixed (i,k). */
        for (jj = jb; jj + 3 < j_max; jj += 4) {
          Ai[jj]     -= aik * Ak[jj];
          Ai[jj + 1] -= aik * Ak[jj + 1];
          Ai[jj + 2] -= aik * Ak[jj + 2];
          Ai[jj + 3] -= aik * Ak[jj + 3];
        }
        for (; jj < j_max; ++jj) {
          Ai[jj] -= aik * Ak[jj];
        }
