   * 2. Forward substitution: solve L * y = b.
   *
   *    L has a unit diagonal and is stored in the strict lower triangle
   *    of A. This loop is inherently sequential in i, but the inner
   *    reduction over j is unrolled for better ILP. The order of
   *    operations in the sum is preserved.
   * ------------------------------------------------------------------*/
  for (i = 0; i < n_pb; ++i) {
    w = b[i];

    int j_end = i & ~3;
    for (j = 0; j < j_end; j += 4) {
      w -= A[i][j]     * y[j];
